<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Jobs - C-Net Library Admin</title><style>*{box-sizing:border-box}body{font-family:Arial,sans-serif;background:#f5f7fb;margin:0;color:#1f2937}.wrap{max-width:1350px;margin:28px auto;padding:0 18px}.top,.inline{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.top{justify-content:space-between;margin-bottom:18px}.grid{display:grid;grid-template-columns:360px 1fr;gap:18px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:14px;padding:18px;margin-bottom:18px}.field{margin-bottom:10px}.row{display:grid;grid-template-columns:1fr 1fr;gap:8px}input,select,textarea{width:100%;padding:8px;border:1px solid #d1d5db;border-radius:8px;margin-top:4px}.btn{border:0;border-radius:8px;padding:9px 12px;background:#111827;color:#fff;text-decoration:none;cursor:pointer;font-weight:700}.alt{background:#0f766e}.danger{background:#b91c1c}.muted{color:#6b7280;font-size:12px}.job{border:1px solid #e5e7eb;border-radius:12px;padding:14px;margin-bottom:12px;background:#fff}.editgrid{display:grid;grid-template-columns:repeat(4,minmax(120px,1fr));gap:8px}.wide{grid-column:span 2}.notice{padding:10px;border-radius:9px;margin-bottom:12px}.ok{background:#f0fdf4}.err{background:#fef2f2}@media(max-width:1000px){.grid{grid-template-columns:1fr}.editgrid{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.editgrid,.row{grid-template-columns:1fr}.wide{grid-column:auto}}</style></head><body><div class="wrap"><div class="top"><div><h1 style="margin:0">Job & Career Management</h1><div class="muted">Create, edit, publish/hide, feature and safely delete job listings.</div></div><a class="btn" href="{{ route('admin.dashboard') }}">Dashboard</a></div>@if(session('success'))<div class="notice ok">{{ session('success') }}</div>@endif @if($errors->any())<div class="notice err"><ul style="margin:0;padding-left:18px">@foreach($errors->all() as $error)<li>{{ 