rivate','internship','apprenticeship'] as $type)<option value="{{ $type }}" @selected(request('type')===$type)>{{ ucfirst($type) }}</option>@endforeach</select><button class="btn">Filter</button></form></div>@forelse($jobs as $job)<div class="job"><div class="top" style="margin-bottom:10px"><div><strong>{{ $job->title }}</strong><div class="muted">{{ $job->organization }} · {{ $job->branch?->name ?? 'Global' }} · Saved by {{ $job->saved_by_students_count }} student(s)</div></div><a href="{{ $job->official_url }}" target="_blank" rel="noopener">Official Link</a></div><form method="POST" action="{{ route('admin.jobs.update',$job) }}">@csrf @method('PATCH')<div class="editgrid"><input name="title" value="{{ $job->title }}" required><input name="organization" value="{{ $job->organization }}" required><select name="job_type">@foreach(['government','private','internship','apprenticeship'] as $type)<option value="{{ $type }}" @selected($job->job_type===$type)>{{ ucfirst($type) }}</option>@endforeach</select><input name="category" value="{{ $job->category }}" placeholder="Category"><input name="qualification" value="{{ $job->qualification }}" placeholder="Qualification"><input name="location" value="{{ $job->location }}" placeholder="Location"><input type="date" name="published_date" value="{{ $job->published_date?->format('Y-m-d') }}"><input type="date" name="last_date" value="{{ $job->last_date?->format('Y-m-d') }}"><select name="branch_id"><option value="">Global / All</option>@foreach($branches as $branch)<option value="{{ $branch->id }}" @selected((int)$job->branch_id===$branch->id)>{{ $branch->name }}</option>@endforeach</select><input class="wide" type="url" name="official_url" value="{{ $job->official_url }}" required><textarea class="wide" name="summary" rows="2" placeholder="Summary">{{ $job->summary }}</textarea></div><div class="inline" style="margin-top:8px"><label><input style="width:auto" type="checkbox" name="is_featured" value="1" @checked($job->is_featured